insert into skills (key, code, note, alias, src, hidden, early_in_term, partial, kind, proof, act, time_estimate, route) values ('Java / Spring Boot', NULL, 'หลักสูตรสอน OOP แต่ไม่สอนเฟรมเวิร์กนี้', 'ค้นคำว่า “Spring” ในเอกสารหลักสูตรทั้งฉบับ = พบ 0 ครั้ง · คำว่า “Java” พบ 1 ครั้ง อยู่ในคำว่า JavaScript', NULL, false, false, false, 'course', 'ประกาศเขียนว่า "เคยใช้ Spring Boot ในโปรเจกต์จริง" ไม่ใช่ "จบสาย Java" — หลักสูตรให้พื้น OOP มาแล้ว เหลือแค่เฟรมเวิร์ก', 'เขียน REST API ตัวที่เคยทำในวิชา คพ.100 ใหม่ด้วย Spring Boot ให้จบทั้งตัว', 'ประมาณ 1–2 สุดสัปดาห์ · ได้ repo เป็นหลักฐาน', NULL);
